const e=document.querySelector(".nav-toggle"),t=document.getElementById("hauptnavigation");if(e&&t){const s=()=>{t.classList.remove("is-open"),e.setAttribute("aria-expanded","false")};e.addEventListener("click",()=>{const n=t.classList.toggle("is-open");e.setAttribute("aria-expanded",String(n))}),document.addEventListener("keydown",n=>{n.key==="Escape"&&t.classList.contains("is-open")&&(s(),e.focus())})}
